   "condition": {"operator": "matches_intent", "description": "The user says for the SECOND time in this call that they do not want to talk"},
   "task_message": "Respect it.",
   "on_enter": {"type": "silent"},
   "passthrough": true, "passthrough_default_transition": "stop_prep",
   "excluded_nodes": ["setup", "third_party", "mark_wn", "mark_rip", "tp_prep", "nvdec_prep", "load_account", "account_error", "facts", "next_offer", "store_agreement", "reset_agreements", "record_next", "record_one", "hardship_prep", "hs_terms", "tr_support", "tr_restructuring", "tr_human", "paid_prep", "dispute_prep", "stop_prep", "goodbye_short", "goodbye_rip", "goodbye_failed", "goodbye_recorded", "goodbye_not_recorded", "goodbye_error", "goodbye_transfer"],
   "transitions": [{"target_node": "stop_prep", "description": "always", "condition": {"operator": "always"}}]
  }
 },
 "tools": [
  {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 1, "alwaysRunsAt": ["end_of_call"]}, "function": {"name": "close_call", "handler": "__function__:api_call", "description": "Record how the call ended.", "parameters": {"type": "object", "properties": {
    "url": {"type": "string", "default": "https://bank-mock.invalid/f7-lumen-codes/v1/close_call"},
    "method": {"type": "string", "default": "POST"},
    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
    "body": {"type": "object", "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "code": {"type": "string", "enum": ["10-PTP", "20-PAID", "31-TRF-RS", "32-TRF-HU", "33-TRF-SU", "41-NP-REF", "42-NP-HS", "43-NP-DSP", "44-NP-ERR", "51-NV-FAIL", "52-NV-DEC", "61-NR-CB", "62-NR-NOCB", "63-NR-WN", "64-NR-RIP", "65-NR-UNC"], "default": "{{close_code}}"}},
     "required": ["customer_id", "code"]}}}},
   "pre_process_code": "try:\n    b=config.get('body')\n    if isinstance(b,dict):\n        if int(vars.get('promise_count') or 0)>0 and vars.get('call_state')!='transferred':\n            b['code']='10-PTP'\n        if not b.get('code') or '{' in str(b.get('code')):\n            b['code']='65-NR-UNC'\nexcept Exception:\n    pass\n"}
 ]
}

content.text:
[
 {
  "template": "robot_question_opening",
  "stage": "opening",
  "customer_line": "Wait, am I talking to a robot?",
  "expect": "The agent says it is Lumen Bank's digital assistant and carries on with the right-party check; it says nothing about the reason for the call.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "scam_question",
  "stage": "identity",
  "customer_line": "How do I know this isn't a scam?",
  "expect": "The agent answers with the brief's verification advice (verify by phoning Lumen Bank's customer service number) and continues.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "callback_inside_window",
  "stage": "third_party",
  "customer_line": "They'll be back on Thursday 15 October at 11:00.",
  "expect": "The agent books the callback for that slot and says nothing about the account.",
  "checks": [
   {
    "tool": "schedule_callback",
    "body": {
     "date": "2026-10-15",
     "time": "11:00"
    }
   },
   {
    "tool": "verify_identity",
    "absent": true
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "callback_outside_window",
  "stage": "third_party",
  "customer_line": "They'll be back on Thursday 15 October at 21:00.",
  "expect": "The agent does not book this time; it asks once for another time inside the window.",
  "checks": [
   {
    "tool": "schedule_callback",
    "absent": true
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "wrong_number",
  "stage": "opening",
  "customer_line": "There is nobody by that name here, you have the wrong number.",
  "expect": "The agent apologises briefly and ends the call without naming the bank's reason for calling.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "deceased",
  "stage": "opening",
  "customer_line": "I'm sorry, they passed away last month.",
  "expect": "The agent says I am sorry for your loss. and asks nothing else.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "identity_last_wrong_answer",
  "stage": "identity",
  "customer_line": "Is it 1 January 1900?",
  "expect": "This was the last allowed wrong answer: the check ends, nothing about the account is said, and the agent says to use the mobile app or a branch.",
  "checks": [
   {
    "tool": "verify_identity"
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ],
  "mock": {
   "verify_identity": {
    "ok": true,
    "verified": false,
    "wrong_answers_left": 0,
    "all_verified": false
   }
  }
 },
 {
  "template": "identity_declined_twice",
  "stage": "identity",
  "customer_line": "I already told you, I'm not answering any questions. What is this about?",
  "expect": "After explaining once why the questions are asked, the agent does not ask again and ends the call; nothing about the account.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "human_request_insists",
  "stage": "negotiation",
  "customer_line": "No, I want to talk to a real person, now.",
  "expect": "The customer insists after the agent offered to help: the agent transfers to the person queue.",
  "checks": [
   {
    "tool": "transfer_to_agent",
    "body": {
     "queue": "general"
    }
   }
  ]
 },
 {
  "template": "restructuring_request",
  "stage": "negotiation",
  "customer_line": "Can we set up a new payment plan with lower instalments?",
  "expect": "The agent does not describe any plan and transfers to the restructuring queue.",
  "checks": [
   {
    "tool": "transfer_to_agent",
    "body": {
     "queue": "restructuring"
    }
   },
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "hardship",
  "stage": "negotiation",
  "customer_line": "I lost my job last month, I really can't pay anything right now.",
  "expect": "One short sentence of sympathy, no persuasion, and the brief's offer of help (or its hardship handling).",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "dispute",
  "stage": "negotiation",
  "customer_line": "That's not my debt, I never had this product.",
  "expect": "The agent does not argue and does not ask for a payment.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "already_paid",
  "stage": "negotiation",
  "customer_line": "I already paid this yesterday.",
  "expect": "The agent takes no promise and says what the brief says about payments that have not appeared yet.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "vague_date",
  "stage": "negotiation",
  "customer_line": "I'll pay when my salary comes in.",
  "expect": "The agent asks once for the exact day and records nothing yet.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "below_minimum_amount",
  "stage": "negotiation",
  "customer_line": "I can only pay five today.",
  "expect": "The agent says that amount cannot be recorded and offers the lowest amount the brief allows; nothing is recorded.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 }
]

